let liqScenario35='base',liqHorizon35=3;
function liqRows35(){const mult=liqScenario35==='downside'?{calls:1.30,dist:.60,fees:1.12}:liqScenario35==='upside'?{calls:.90,dist:1.25,fees:.95}:{calls:1,dist:1,fees:1};return liquidityBase.slice(0,liqHorizon35).map(x=>({...x,calls:x.calls*mult.calls,dist:x.dist*mult.dist,fees:x.fees*mult.fees}))}
function liqCalc35(){const rows=liqRows35(),start=7.20;let cash=start,minCash=start;rows.forEach(r=>{cash+=r.dist-r.calls-r.fees-r.other;minCash=Math.min(minCash,cash)});const calls=rows.reduce((a,r)=>a+r.calls,0),dist=rows.reduce((a,r)=>a+r.dist,0),fees=rows.reduce((a,r)=>a+r.fees+r.other,0),net=dist-calls-fees,obligation=Math.max(...rows.map(r=>r.calls+r.fees+r.other)),coverage=minCash/(obligation||1);return{rows,start,calls,dist,fees,net,end:cash,minCash,coverage}}
function liqSvg35(){const d=liqCalc35(),rows=d.rows,W=820,H=280,L=48,R=62,T=24,B=44,plotW=W-L-R,plotH=H-T-B,maxFlow=Math.max(...rows.flatMap(r=>[r.calls+r.fees+r.other,r.dist]))*1.25,maxCash=Math.max(d.start,...(()=>{let c=d.start;return rows.map(r=>c+=r.dist-r.calls-r.fees-r.other)})())*1.10,minCash=Math.min(0,d.minCash*.85),x=i=>L+plotW*(i+.5)/rows.length,barW=Math.min(34,plotW/rows.length*.38),flowY=v=>T+plotH*.58*(1-v/maxFlow),zeroY=T+plotH*.58,cashY=v=>T+plotH*(1-(v-minCash)/(maxCash-minCash));let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Private market cashflow and liquidity forecast">`;
 for(let i=0;i<=4;i++){const y=T+plotH*i/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y}" y2="${y}" stroke="#e8edf3"/><text x="${L-7}" y="${y+3}" text-anchor="end" font-size="9" fill="#718197">${(maxCash*(1-i/4)).toFixed(1)}m</text>`}
 svg+=`<line x1="${L}" x2="${W-R}" y1="${zeroY}" y2="${zeroY}" stroke="#cfd8e5"/>`;
 let cash=d.start,pts=[];rows.forEach((r,i)=>{const xx=x(i),callH=(r.calls+r.fees+r.other)/maxFlow*(plotH*.40),distH=r.dist/maxFlow*(plotH*.40);svg+=`<rect x="${xx-barW-2}" y="${zeroY}" width="${barW}" height="${callH}" rx="3" fill="#1d5cff" opacity=".82"/><rect x="${xx+2}" y="${zeroY-distH}" width="${barW}" height="${distH}" rx="3" fill="#05a8c7" opacity=".86"/><rect x="${xx-barW-2}" y="${zeroY}" width="${barW}" height="${(r.fees+r.other)/maxFlow*(plotH*.40)}" rx="3" fill="#a8b5c7" opacity=".88"/>`;cash+=r.dist-r.calls-r.fees-r.other;pts.push([xx,cashY(cash),cash]);svg+=`<text x="${xx}" y="${H-15}" text-anchor="middle" font-size="9" fill="#6f7e92">${r.m}</text>`});
 const pd=pts.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');svg+=`<path d="${pd}" fill="none" stroke="#121d2f" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/>`;pts.forEach(p=>svg+=`<circle cx="${p[0]}" cy="${p[1]}" r="3.5" fill="#fff" stroke="#121d2f" stroke-width="2"/>`);const floor=1.25,fy=cashY(Math.max(0,d.minCash/floor));svg+=`<line x1="${L}" x2="${W-R}" y1="${fy}" y2="${fy}" stroke="#d78b11" stroke-dasharray="6 5"/><text x="${W-R}" y="${fy-5}" text-anchor="end" font-size="8.5" fill="#9b6508">house liquidity floor</text></svg>`;return svg}
function renderLiquidity35(){const host=$('#v35LiquidityPanel');if(!host)return;const d=liqCalc35(),coverage=Math.max(0,Math.min(100,d.coverage/2*100)),events=d.rows.flatMap(r=>r.events.map(e=>({month:r.m,date:e[0],name:e[1],type:e[2],amount:e[3],prob:e[4]}))).slice(0,4);host.innerHTML=`<div class="v35-liq-head"><div><div class="v35-kicker">LIQUIDITY PLANNING · PRIVATE MARKETS</div><h2>Private-market cashflow forecast</h2><p>Commitment-level calls and distributions are probability-weighted into the whole-portfolio cash runway, with stressed pacing, funding sources and the house liquidity floor visible on the same chart.</p></div><div class="v35-liq-controls"><div class="v35-tabs">${[['base','Base'],['downside','Downside'],['upside','Upside']].map(x=>`<button class="${liqScenario35===x[0]?'active':''}" data-v35-liq-scenario="${x[0]}">${x[1]}</button>`).join('')}</div><div class="v35-tabs">${[[3,'90D'],[6,'6M'],[12,'12M']].map(x=>`<button class="${liqHorizon35===x[0]?'active':''}" data-v35-liq-horizon="${x[0]}">${x[1]}</button>`).join('')}</div></div></div><div class="v35-liq-kpis"><div class="v35-liq-metric"><span>Opening liquid assets</span><strong>${money(d.start,'US$')}m</strong><small>Cash + eligible short term</small></div><div class="v35-liq-metric"><span>Projected calls</span><strong>US$ ${d.calls.toFixed(2)}m</strong><small>${liqScenario35} pacing</small></div><div class="v35-liq-metric"><span>Expected distributions</span><strong>US$ ${d.dist.toFixed(2)}m</strong><small>Probability weighted</small></div><div class="v35-liq-metric"><span>Fees / other</span><strong>US$ ${d.fees.toFixed(2)}m</strong><small>Management + direct funding</small></div><div class="v35-liq-metric"><span>Net private cashflow</span><strong>${d.net<0?'−':'+'}US$ ${Math.abs(d.net).toFixed(2)}m</strong><small>${liqHorizon35===3?'90-day':liqHorizon35+'-month'} horizon</small></div><div class="v35-liq-metric"><span>Ending liquid assets</span><strong>${d.end<0?'−':''}US$ ${Math.abs(d.end).toFixed(2)}m</strong><small>Before new public-market trades</small></div></div><div class="v35-liq-body"><section class="v35-liq-chart-card"><div class="v35-liq-chart-meta"><strong>Monthly calls, distributions and liquidity runway</strong><div class="v35-liq-legend"><span><i></i>Calls</span><span class="dist"><i></i>Distributions</span><span class="fees"><i></i>Fees/other</span><span class="line"><i></i>Liquid assets</span></div></div><div class="v35-liq-chart">${liqSvg35()}</div></section><aside class="v35-liq-side"><div class="v35-liq-gauge"><div class="v35-ring" style="--pct:${coverage.toFixed(0)};--ring:${d.coverage>=1.25?'#087b63':'#c52f48'}"><div><strong>${d.coverage.toFixed(2)}×</strong><small>cover</small></div></div><div><h3>Minimum liquidity cover</h3><p>${d.coverage>=1.25?'Above the 1.25× house floor in this scenario.':'Below the 1.25× house floor; funding action is required before new commitments.'}</p></div></div><div class="v35-funding-stack"><h3>Funding waterfall</h3><div class="v35-fund-line"><span>1 · USD operating cash</span><strong>US$ 3.42m</strong></div><div class="v35-fund-line"><span>2 · T-bills / MMF same-day</span><strong>US$ 2.08m</strong></div><div class="v35-fund-line"><span>3 · Committed liquidity line</span><strong>US$ 1.70m</strong></div><div class="v35-fund-line"><span>Reserved for margin / settlement</span><strong>US$ 0.84m</strong></div><button class="v35-btn" style="width:100%;margin-top:8px" id="v35FundingPlan">Open funding plan</button></div></aside></div><div class="v35-liq-events"><div class="v35-liq-events-head"><strong>Next material private-market cash events</strong><button class="v35-btn small" id="v35StressLiquidity">Create stress case</button></div><div class="v35-liq-event-grid">${events.map(e=>`<div class="v35-liq-event ${e.type.toLowerCase().includes('distribution')||e.type.toLowerCase().includes('interest')?'dist':e.type.toLowerCase().includes('fee')?'fee':'call'}" data-v35-liq-event="${esc(e.name)}"><span>${esc(e.date)} · ${esc(e.prob)} confidence</span><strong>${esc(e.name)}</strong><small>${esc(e.type)} · ${esc(e.month)} cash plan</small><em>${e.type.toLowerCase().includes('distribution')||e.type.toLowerCase().includes('interest')?'+':'−'}US$ ${esc(e.amount)}</em></div>`).join('')}</div></div>`;$$('[data-v35-liq-scenario]',host).forEach(b=>b.onclick=()=>{liqScenario35=b.dataset.v35LiqScenario;renderLiquidity35()});$$('[data-v35-liq-horizon]',host).forEach(b=>b.onclick=()=>{liqHorizon35=+b.dataset.v35LiqHorizon;renderLiquidity35()});$('#v35FundingPlan',host).onclick=openFundingPlan35;$('#v35StressLiquidity',host).onclick=()=>{liqScenario35='downside';renderLiquidity35();toast('Downside liquidity stress applied','Calls accelerated, distributions haircut and fees stressed. Review the funding waterfall before committing more cash.')};$$('[data-v35-liq-event]',host).forEach(x=>x.onclick=()=>openLiquidityEvent35(x.dataset.v35LiqEvent))}
function openFundingPlan35(){const d=liqCalc35();openModal({eyebrow:'PRIVATE MARKETS · FUNDING PLAN',title:'Convert the forecast into controlled funding actions',subtitle:'Liquidity planning links private calls to cash, same-day instruments, credit capacity and settlement/margin reservations.',wide:true,body:`<div class="v35-grid"><section class="v35-card v35-span-7"><div class="v35-card-head"><div><div class="v35-kicker">FUNDING WATERFALL</div><h2>Recommended sequencing</h2></div></div><div class="v35-card-body"><div class="v35-list"><div class="v35-row"><span><strong>Keep operational reserve intact</strong><small>Settlement + margin + client redemptions</small></span><em>US$ 0.84m</em></div><div class="v35-row"><span><strong>Use free USD cash</strong><small>Available without liquidation</small></span><em>US$ 3.42m</em></div><div class="v35-row"><span><strong>Mature / sell eligible T-bills</strong><small>Same-day / T+1 liquidity</small></span><em>US$ 2.08m</em></div><div class="v35-row"><span><strong>Liquidity line headroom</strong><small>Only if downside call pacing materialises</small></span><em>US$ 1.70m</em></div></div></div></section><aside class="v35-card v35-span-5"><div class="v35-card-head"><div><div class="v35-kicker">CURRENT SCENARIO</div><h2>${liqScenario35[0].toUpperCase()+liqScenario35.slice(1)}</h2></div></div><div class="v35-card-body"><div class="v35-list"><div class="v35-row"><span><strong>Net private cashflow</strong></span><em>${d.net.toFixed(2)}m</em></div><div class="v35-row"><span><strong>Minimum liquidity</strong></span><em>${d.minCash<0?'−':''}US$ ${Math.abs(d.minCash).toFixed(2)}m</em></div><div class="v35-row"><span><strong>Coverage</strong></span><em>${d.coverage.toFixed(2)}×</em></div></div><button class="v35-btn primary" style="width:100%;margin-top:9px" onclick="document.querySelector('#v35Modal .v34-modal-close').click()">Save funding scenario</button></div></aside></div>`})}
function openLiquidityEvent35(name){openModal({eyebrow:'PRIVATE MARKET · CASH EVENT',title:esc(name),subtitle:'Commitment-level obligation with funding and evidence controls.',body:`<div class="v35-list"><div class="v35-row"><span><strong>Notice / source</strong><small>GP capital-call notice or distribution advice</small></span><em>Controlled document</em></div><div class="v35-row"><span><strong>Probability</strong><small>Modelled from current notice / pacing assumptions</small></span><em>Scenario input</em></div><div class="v35-row"><span><strong>Funding source</strong><small>Assigned through the whole-portfolio funding waterfall</small></span><em>Not yet reserved</em></div><div class="v35-row"><span><strong>Approval</strong><small>Treasury / Operations release under maker-checker</small></span><em>Required</em></div></div>`})}
