function sparkSvg(seed){let h=[...seed].reduce((a,c)=>a+c.charCodeAt(0),0),pts=[];for(let i=0;i<16;i++){const y=8+Math.sin((i+h%7)*.78)*3+((h+i*13)%5-2);pts.push(`${(i*4.4).toFixed(1)},${Math.max(2,Math.min(14,y)).toFixed(1)}`)}return `<svg class="v35-mini-spark" viewBox="0 0 68 16" aria-hidden="true"><polyline points="${pts.join(' ')}" fill="none" stroke="#5f83ef" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function cleanTickerText(root){if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(/\b[A-Z][A-Z0-9]{1,9}\.(ZW|VX)\b/.test(n.nodeValue))n.nodeValue=stripTicker(n.nodeValue)}}
